/* Private fixtures are generated by verify_original_aerotech.py from supplied
 * game files. No game bytes are compiled into this test or distributed. */
#include "mercscareer.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static size_t read_file(const char *dir,const char *name,const char *suffix,uint8_t *b,size_t cap)
{
    char path[4096];FILE *f;size_t n;
    assert(snprintf(path,sizeof path,"%s/%s.%s",dir,name,suffix)<(int)sizeof path);
    f=fopen(path,"rb");assert(f);n=fread(b,1,cap,f);assert(!ferror(f)&&feof(f));fclose(f);return n;
}
int main(int argc,char **argv)
{
    static const char *const names[]={"ARO00STD","ARO01STD","ARO02STD"};int i;
    assert(argc==2);
    for(i=0;i<3;i++){
        uint8_t raw[4096],expected[4096],output[MERCS_CAREER_DEPLOY_MAX_BYTES];size_t n,written;
        mercs_career_mech_pair pair;char name[32];
        n=read_file(argv[1],names[i],"raw",raw,sizeof raw);snprintf(name,sizeof name,"%.5sMER.MEK",names[i]);
        assert(!mercs_career_pair_init(&pair,raw,n,name,17,-1));
        n=read_file(argv[1],names[i],"record",expected,sizeof expected);assert(n==sizeof pair.current);
        if(memcmp(pair.current.bytes,expected,n)){
            size_t j;for(j=0;j<n;j++)if(pair.current.bytes[j]!=expected[j])fprintf(stderr,"%s offset%zx native%02x original%02x\n",names[i],j,pair.current.bytes[j],expected[j]);
            abort();
        }
        assert(!mercs_career_deployment_bytes(&pair.current,output,sizeof output,&written));
        n=read_file(argv[1],names[i],"deploy",expected,sizeof expected);assert(n==written&&!memcmp(expected,output,n));
    }
    puts("PASS: three original AeroTech complete records and deployment files");return 0;
}
